package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"go/types"
	"sort"
	"strconv"
	"strings"
)

// Generate returns the Go source of the generated file for the contract: the
// Wasm exports for contract functions, the Val conversions of contract types,
// event publishing, and contract clients.
func (m *Model) Generate() ([]byte, error) {
	g := &generator{m: m, imports: map[string]string{SDKPath: "soroban"}}
	var body bytes.Buffer
	g.w = &body

	for _, u := range m.Types {
		g.udt(u)
	}
	for _, e := range m.Events {
		g.event(e)
	}
	for _, c := range m.Clients {
		g.client(c)
	}
	{
		for _, f := range m.Functions {
			g.export(f)
		}
	}

	var out bytes.Buffer
	out.WriteString("// Code generated by soroban-go. DO NOT EDIT.\n\n")
	fmt.Fprintf(&out, "package %s\n\n", m.PkgName)
	var paths []string
	for p := range g.imports {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	out.WriteString("import (\n")
	for _, p := range paths {
		fmt.Fprintf(&out, "\t%s %q\n", g.imports[p], p)
	}
	out.WriteString(")\n\n")
	out.Write(body.Bytes())
	src, err := format.Source(out.Bytes())
	if err != nil {
		return out.Bytes(), fmt.Errorf("formatting generated code: %w", err)
	}
	return src, nil
}

type generator struct {
	m       *Model
	w       *bytes.Buffer
	imports map[string]string
	tmp     int
}

func (g *generator) p(format string, args ...any) {
	fmt.Fprintf(g.w, format, args...)
	g.w.WriteByte('\n')
}

func (g *generator) typ(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		if p == g.m.Pkg {
			return ""
		}
		if name, ok := g.imports[p.Path()]; ok {
			return name
		}
		name := p.Name()
		for _, n := range g.imports {
			if n == name {
				name = fmt.Sprintf("%s%d", p.Name(), len(g.imports))
			}
		}
		g.imports[p.Path()] = name
		return name
	})
}

func basicKind(t types.Type) (types.BasicKind, bool) {
	if b, ok := t.(*types.Basic); ok {
		return b.Kind(), true
	}
	return 0, false
}

// toVal returns an expression converting expr of type t to a soroban.Val.
func (g *generator) toVal(expr string, t types.Type) string {
	if k, ok := basicKind(t); ok {
		switch k {
		case types.Bool:
			return "soroban.ValFromBool(" + expr + ")"
		case types.Uint32:
			return "soroban.ValFromU32(" + expr + ")"
		case types.Int32:
			return "soroban.ValFromI32(" + expr + ")"
		case types.Uint64:
			return "soroban.ValFromU64(" + expr + ")"
		case types.Int64:
			return "soroban.ValFromI64(" + expr + ")"
		}
	}
	if n, ok := types.Unalias(t).(*types.Named); ok {
		if _, ok := n.Underlying().(*types.Basic); ok && n.Obj().Pkg() == g.m.Pkg {
			// Enums and errors are basic types with generated methods.
			return expr + ".ToVal()"
		}
	}
	return expr + ".ToVal()"
}

// fromVal returns an expression converting the soroban.Val expr to type t.
func (g *generator) fromVal(expr string, t types.Type) string {
	if k, ok := basicKind(t); ok {
		switch k {
		case types.Bool:
			return "soroban.BoolFromVal(" + expr + ")"
		case types.Uint32:
			return "soroban.U32FromVal(" + expr + ")"
		case types.Int32:
			return "soroban.I32FromVal(" + expr + ")"
		case types.Uint64:
			return "soroban.U64FromVal(" + expr + ")"
		case types.Int64:
			return "soroban.I64FromVal(" + expr + ")"
		}
	}
	return "soroban.FromVal[" + g.typ(t) + "](" + expr + ")"
}

func quoteList(names []string) string {
	q := make([]string, len(names))
	for i, n := range names {
		q[i] = strconv.Quote(n)
	}
	return strings.Join(q, ", ")
}

func (g *generator) udt(u *UDT) {
	name := u.Obj.Name()
	switch u.Kind {
	case KindStruct:
		var keys []string
		for _, f := range u.Fields {
			keys = append(keys, f.Name)
		}
		g.p("var _soroban_keys_%s = []string{%s}\n", name, quoteList(keys))
		g.p("// ToVal implements soroban.ToValer.")
		g.p("func (v %s) ToVal() soroban.Val {", name)
		var vals []string
		for _, f := range u.Fields {
			vals = append(vals, g.toVal("v."+f.GoName, f.Type))
		}
		g.p("return soroban.StructToVal(_soroban_keys_%s, []soroban.Val{%s})", name, strings.Join(vals, ", "))
		g.p("}\n")
		g.p("// FromVal implements soroban.FromValer.")
		g.p("func (v *%s) FromVal(x soroban.Val) {", name)
		g.p("var vals [%d]soroban.Val", len(u.Fields))
		g.p("soroban.StructFromVal(x, _soroban_keys_%s, vals[:])", name)
		for i, f := range u.Fields {
			g.p("v.%s = %s", f.GoName, g.fromVal(fmt.Sprintf("vals[%d]", i), f.Type))
		}
		g.p("}\n")
	case KindTuple:
		g.p("// ToVal implements soroban.ToValer.")
		g.p("func (v %s) ToVal() soroban.Val {", name)
		var vals []string
		for _, f := range u.Fields {
			vals = append(vals, g.toVal("v."+f.GoName, f.Type))
		}
		g.p("return soroban.TupleToVal([]soroban.Val{%s})", strings.Join(vals, ", "))
		g.p("}\n")
		g.p("// FromVal implements soroban.FromValer.")
		g.p("func (v *%s) FromVal(x soroban.Val) {", name)
		g.p("var vals [%d]soroban.Val", len(u.Fields))
		g.p("soroban.TupleFromVal(x, vals[:])")
		for i, f := range u.Fields {
			g.p("v.%s = %s", f.GoName, g.fromVal(fmt.Sprintf("vals[%d]", i), f.Type))
		}
		g.p("}\n")
	case KindEnum:
		g.p("// ToVal implements soroban.ToValer.")
		g.p("func (v %s) ToVal() soroban.Val { return soroban.EnumToVal(uint32(v)) }\n", name)
		g.p("// FromVal implements soroban.FromValer.")
		g.p("func (v *%s) FromVal(x soroban.Val) {", name)
		g.p("switch c := %s(soroban.EnumFromVal(x)); c {", name)
		g.enumCaseList(u)
		g.p("*v = c")
		g.p("default:\nsoroban.ConversionError()")
		g.p("}\n}\n")
	case KindError:
		g.p("// ToError implements soroban.ErrorValuer.")
		g.p("func (v %s) ToError() soroban.Error { return soroban.ErrorFromContractCode(uint32(v)) }\n", name)
		g.p("// ToVal implements soroban.ToValer.")
		g.p("func (v %s) ToVal() soroban.Val { return v.ToError().ToVal() }\n", name)
		g.p("// Error implements error.")
		g.p("func (v %s) Error() string {", name)
		g.p("switch v {")
		for _, c := range u.Cases {
			g.p("case %s:\nreturn %q", c.GoName, c.Name)
		}
		g.p("}\nreturn %q\n}\n", name)
		g.p("// FromVal implements soroban.FromValer.")
		g.p("func (v *%s) FromVal(x soroban.Val) {", name)
		g.p("switch c := %s(soroban.ContractErrorFromVal(x)); c {", name)
		g.enumCaseList(u)
		g.p("*v = c")
		g.p("default:\nsoroban.ConversionError()")
		g.p("}\n}\n")
	case KindUnion:
		var cases []string
		for _, f := range u.Fields {
			cases = append(cases, f.Name)
		}
		g.p("var _soroban_cases_%s = []string{%s}\n", name, quoteList(cases))
		g.p("// ToVal implements soroban.ToValer.")
		g.p("func (v %s) ToVal() soroban.Val {", name)
		g.p("switch {")
		for _, f := range u.Fields {
			if f.Void {
				g.p("case v.%s:\nreturn soroban.UnionToVal(%q)", f.GoName, f.Name)
				continue
			}
			var vals []string
			if len(f.Elems) == 1 && !isTuplePtr(f.Type) {
				vals = append(vals, g.toVal("(*v."+f.GoName+")", f.Elems[0]))
			} else {
				for i, e := range f.Elems {
					vals = append(vals, g.toVal(fmt.Sprintf("v.%s.V%d", f.GoName, i), e))
				}
			}
			g.p("case v.%s != nil:\nreturn soroban.UnionToVal(%q, %s)", f.GoName, f.Name, strings.Join(vals, ", "))
		}
		g.p("}\nsoroban.ConversionError()\nreturn soroban.ValVoid\n}\n")
		g.p("// FromVal implements soroban.FromValer.")
		g.p("func (v *%s) FromVal(x soroban.Val) {", name)
		g.p("idx, vec := soroban.UnionFromVal(x, _soroban_cases_%s)", name)
		g.p("*v = %s{}", name)
		g.p("switch idx {")
		for i, f := range u.Fields {
			g.p("case %d:", i)
			if f.Void {
				g.p("soroban.UnionCaseFromVal(vec, nil)\nv.%s = true", f.GoName)
				continue
			}
			g.p("var f [%d]soroban.Val\nsoroban.UnionCaseFromVal(vec, f[:])", len(f.Elems))
			pt := f.Type.(*types.Pointer)
			if len(f.Elems) == 1 && !isTuplePtr(f.Type) {
				g.p("c := %s", g.fromVal("f[0]", f.Elems[0]))
			} else {
				g.p("var c %s", g.typ(pt.Elem()))
				for j, e := range f.Elems {
					g.p("c.V%d = %s", j, g.fromVal(fmt.Sprintf("f[%d]", j), e))
				}
			}
			g.p("v.%s = &c", f.GoName)
		}
		g.p("default:\nsoroban.ConversionError()")
		g.p("}\n}\n")
	}
}

func isTuplePtr(t types.Type) bool {
	p, ok := t.(*types.Pointer)
	if !ok {
		return false
	}
	_, ok = tupleElems(p.Elem())
	return ok
}

func (g *generator) enumCaseList(u *UDT) {
	if len(u.Cases) == 0 {
		g.p("case %s(0xffffffff):", u.Obj.Name())
		return
	}
	var names []string
	for _, c := range u.Cases {
		names = append(names, c.GoName)
	}
	g.p("case %s:", strings.Join(names, ", "))
}

func symbolExpr(s string) string {
	if len(s) <= 9 {
		return fmt.Sprintf("soroban.SymbolShort(%q)", s)
	}
	return fmt.Sprintf("soroban.SymbolFromStr(%q)", s)
}

func (g *generator) event(e *Event) {
	name := e.Obj.Name()
	var topics []string
	for _, t := range e.PrefixTopics {
		topics = append(topics, symbolExpr(t)+".ToVal()")
	}
	var data []Field
	for _, f := range e.Fields {
		if f.Topic {
			topics = append(topics, g.toVal("e."+f.GoName, f.Type))
		} else {
			data = append(data, f)
		}
	}
	g.p("// Topics implements soroban.Event.")
	g.p("func (e %s) Topics() soroban.Vec[soroban.Val] {", name)
	g.p("return soroban.VecFromVals(%s)", strings.Join(topics, ", "))
	g.p("}\n")
	g.p("// Data implements soroban.Event.")
	g.p("func (e %s) Data() soroban.Val {", name)
	switch e.DataFormat {
	case 0: // single value
		if len(data) == 0 {
			g.p("return soroban.ValVoid")
		} else {
			g.p("return %s", g.toVal("e."+data[0].GoName, data[0].Type))
		}
	case 1: // vec
		var vals []string
		for _, f := range data {
			vals = append(vals, g.toVal("e."+f.GoName, f.Type))
		}
		g.p("return soroban.VecFromVals(%s).ToVal()", strings.Join(vals, ", "))
	default: // map
		sorted := append([]Field{}, data...)
		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
		var keys, vals []string
		for _, f := range sorted {
			keys = append(keys, f.Name)
			vals = append(vals, g.toVal("e."+f.GoName, f.Type))
		}
		fn := "StructToVal"
		if e.Sparse {
			fn = "SparseStructToVal"
		}
		g.p("return soroban.%s([]string{%s}, []soroban.Val{%s})", fn, quoteList(keys), strings.Join(vals, ", "))
	}
	g.p("}\n")
	g.p("// Publish publishes the event.")
	g.p("func (e %s) Publish(env soroban.Env) { env.Events().PublishEvent(e) }\n", name)
}

func (g *generator) client(c *Client) {
	g.p("// %s is a client for calling contracts that implement %s.", c.Name, c.Iface.Name())
	g.p("type %s struct {\nAddress soroban.Address\n}\n", c.Name)
	g.p("// New%s returns a client for the contract at the address.", c.Name)
	g.p("func New%s(address soroban.Address) %s { return %s{Address: address} }\n", c.Name, c.Name, c.Name)
	for _, f := range c.Methods {
		var params, args []string
		for _, p := range f.Params {
			n := "arg_" + p.Name
			params = append(params, n+" "+g.typ(p.Type))
			args = append(args, g.toVal(n, p.Type))
		}
		argsExpr := fmt.Sprintf("soroban.VecFromVals(%s)", strings.Join(args, ", "))
		res := "soroban.Void"
		if f.Result != nil {
			res = g.typ(f.Result)
		}
		g.p("// %s invokes the contract function %s. If the invocation fails, the current invocation fails too.", f.Method, f.Name)
		if f.Result != nil {
			g.p("func (c %s) %s(%s) %s {", c.Name, f.Method, strings.Join(params, ", "), res)
			g.p("return soroban.InvokeContract[%s](c.Address, %s, %s)", res, symbolExpr(f.Name), argsExpr)
		} else {
			g.p("func (c %s) %s(%s) {", c.Name, f.Method, strings.Join(params, ", "))
			g.p("soroban.InvokeContract[soroban.Val](c.Address, %s, %s)", symbolExpr(f.Name), argsExpr)
		}
		g.p("}\n")
		g.p("// Try%s invokes the contract function %s, returning the error if the invocation fails.", f.Method, f.Name)
		g.p("func (c %s) Try%s(%s) (%s, *soroban.Error) {", c.Name, f.Method, strings.Join(params, ", "), res)
		g.p("return soroban.TryInvokeContract[%s](c.Address, %s, %s)", res, symbolExpr(f.Name), argsExpr)
		g.p("}\n")
	}
}

func (g *generator) export(f *Function) {
	var params, args []string
	if f.HasEnv {
		args = append(args, "soroban.Env{}")
	}
	for i, p := range f.Params {
		params = append(params, fmt.Sprintf("a%d", i))
		args = append(args, g.fromVal(fmt.Sprintf("soroban.Val(a%d)", i), p.Type))
	}
	sig := ""
	if len(params) > 0 {
		sig = strings.Join(params, ", ") + " uint64"
	}
	g.p("//export %s", f.Name)
	g.p("func _soroban_export_%s(%s) uint64 {", f.Name, sig)
	g.p("soroban.EnsureInit()")
	g.p("var c %s", f.Contract.Name())
	call := fmt.Sprintf("c.%s(%s)", f.Method, strings.Join(args, ", "))
	errVal := func(e string) string {
		if isErrorInterface(f.ErrType) {
			return "soroban.ErrorValOf(" + e + ")"
		}
		return "(*" + e + ").ToVal()"
	}
	switch {
	case f.ErrType != nil && f.Result != nil:
		g.p("r, err := %s", call)
		g.p("if err != nil {\nreturn uint64(%s)\n}", errVal("err"))
		g.p("return uint64(%s)", g.toVal("r", f.Result))
	case f.ErrType != nil:
		g.p("if err := %s; err != nil {\nreturn uint64(%s)\n}", call, errVal("err"))
		g.p("return uint64(soroban.ValVoid)")
	case f.Result != nil:
		g.p("return uint64(%s)", g.toVal(call, f.Result))
	default:
		g.p("%s", call)
		g.p("return uint64(soroban.ValVoid)")
	}
	g.p("}\n")
}
